import { LimoClient, WRAPPED_SOL_MINT } from '@kamino-finance/limo-sdk';
import { RouteOutput, RouteParams } from './types';
import { getRouterTypeID, ROUTER_PROGRAM_MAP, RouterType, TRITON_VOTE_ACCOUNT } from '../consts';
import BN from 'bn.js';
import { getLimoProgramId } from '@kamino-finance/limo-sdk/dist/utils';
import { Address, createNoopSigner, Instruction } from '@solana/kit';
import { DISCRIMINATOR as LOG_USER_BALANCES_START_DISCRIM } from '@kamino-finance/limo-sdk/dist/rpc_client/instructions/logUserSwapBalancesStart';
import { DISCRIMINATOR as LOG_USER_BALANCES_END_DISCRIM } from '@kamino-finance/limo-sdk/dist/rpc_client/instructions/logUserSwapBalancesEnd';

export async function wrapLimoLogsAroundRoute(args: {
  route: RouteOutput;
  params: RouteParams;
  limoClient: LimoClient;
  inputTokenAccount: Address;
  outputTokenAccount: Address;
  nextBestAmountOutSimulated: BN;
  nextBestRouterTypeId: number;
}): Promise<RouteOutput> {
  const {
    route,
    params,
    limoClient,
    inputTokenAccount,
    outputTokenAccount,
    nextBestAmountOutSimulated,
    nextBestRouterTypeId,
  } = args;
  if (route.ixsRouter !== undefined && route.routerType !== 'per' && route.routerType !== 'jupiterZ') {
    const amountOutSimulated =
      params.swapType === 'exactIn' ? route.amountsExactIn.amountOutSimulated : route.amountsExactOut.amountOut;
    const simulatedTs = route.simulationResult?.simulationTimestamp
      ? new BN(route.simulationResult.simulationTimestamp)
      : new BN(0);
    const minimumAmountOut =
      params.swapType === 'exactIn' ? route.amountsExactIn.amountOutGuaranteed : route.amountsExactOut.amountOut;
    const amountIn = params.swapType === 'exactIn' ? route.amountsExactIn.amountIn : route.amountsExactOut.amountIn;
    const logSwapUserBalanceIx = await limoClient.logUserSwapBalancesIxs({
      user: createNoopSigner(params.executor),
      inputMint: params.tokenIn,
      outputMint: params.tokenOut,
      inputTa: inputTokenAccount,
      outputTa: outputTokenAccount,
      swapProgarmId: ROUTER_PROGRAM_MAP[route.routerType],
      simulatedSwapAmountOut: amountOutSimulated ? amountOutSimulated : new BN(0),
      simulatedTs,
      minimumAmountOut: minimumAmountOut,
      swapAmountIn: amountIn,
      simulatedAmountOutNextBest: nextBestAmountOutSimulated,
      aggregatorId: getRouterTypeID(route.routerType), // only 4 chars supported for router name in SC
      nextBestAggregatorId: nextBestRouterTypeId,
      pdaReferrer: params.referrerPda ? params.referrerPda : limoClient.getProgramID(),
      voteAccount: TRITON_VOTE_ACCOUNT,
    });

    route.ixsRouter = insertAroundRouterInstruction(
      route.ixsRouter,
      route.routerType,
      logSwapUserBalanceIx.beforeSwapIx,
      logSwapUserBalanceIx.afterSwapIx,
      params,
    );
  }

  return route;
}

export function insertAroundRouterInstruction(
  instructions: Instruction[],
  routerType: RouterType,
  beforeInstruction: Instruction,
  afterInstruction: Instruction,
  params: RouteParams,
): Instruction[] {
  try {
    const programId = ROUTER_PROGRAM_MAP[routerType];

    let targetIndex = -1;
    const matchingIxsIndex: number[] = [];
    instructions.forEach(
      (instruction, index) => instruction.programAddress === programId && matchingIxsIndex.push(index),
    );
    if (routerType === 'raydium' || routerType === 'dflow') {
      // For raydium and dflow they add wrap and unwrap sol instructions
      // as separate ixs before and after the swap but are part of their
      // program id.
      if (matchingIxsIndex.length === 0) {
        return instructions;
      }

      if (params.tokenIn === WRAPPED_SOL_MINT && params.wrapAndUnwrapSol) {
        if (matchingIxsIndex.length > 1) {
          targetIndex = matchingIxsIndex[1];
        } else {
          targetIndex = matchingIxsIndex[0];
        }
      } else {
        targetIndex = matchingIxsIndex[0];
      }
    } else {
      if (matchingIxsIndex.length > 1 || matchingIxsIndex.length === 0) {
        return instructions;
      }
      targetIndex = matchingIxsIndex[0];
    }

    if (targetIndex === -1) {
      throw new Error(`${routerType}: Instruction for router not found`);
    }

    const result = [...instructions];

    result.splice(targetIndex, 0, beforeInstruction);
    result.splice(targetIndex + 2, 0, afterInstruction);

    return result;
  } catch (error) {
    return instructions;
  }
}

export function removeLimoLogsIxns(ixns: Instruction[]): Instruction[] {
  return ixns.filter((ix) => !isLimoLogsIx(ix));
}

export function includeLimoLogs(incldueLimoLogs: boolean | undefined, routerType?: RouterType): boolean {
  if (routerType === 'per' || routerType === 'jupiterZ' || routerType === 'clover') {
    return false;
  }
  if (incldueLimoLogs === undefined) {
    return true;
  }
  return incldueLimoLogs;
}

function isLimoLogsIx(ix: Instruction): boolean {
  const limoProgramId = getLimoProgramId();
  if (ix.programAddress !== limoProgramId || ix.data === undefined) {
    return false;
  }
  const discriminator = ix.data?.subarray(0, 8);
  return (
    buffersEqual(discriminator, new Uint8Array(LOG_USER_BALANCES_START_DISCRIM)) ||
    buffersEqual(discriminator, new Uint8Array(LOG_USER_BALANCES_END_DISCRIM))
  );
}

function buffersEqual(buf1: Uint8Array, buf2: Uint8Array) {
  return buf1.length === buf2.length && buf1.every((val, i) => val === buf2[i]);
}
